<?php
require_once __DIR__ . '/_layout.php';
$category = trim((string) ($_GET['category'] ?? ''));
$status = trim((string) ($_GET['status'] ?? ''));
$where = ['1=1']; $params = [];
if (in_array($category, report_categories(), true)) { $where[] = 'category=?'; $params[] = $category; }
if (in_array($status, report_statuses(), true)) { $where[] = 'status=?'; $params[] = $status; }
$stmt = db()->prepare('SELECT report_id AS id, reference_number, report_title, category, location, barangay, latitude, longitude, status FROM reports WHERE ' . implode(' AND ', $where) . ' ORDER BY created_at DESC LIMIT 300');
$stmt->execute($params); $rows = $stmt->fetchAll();
admin_header('Manage map locations');
?>
<section class="surface-card mb-3"><form class="row g-2 align-items-end"><div class="col-md-5"><label class="form-label">Category</label><select class="form-select" name="category"><option value="">All categories</option><?php foreach (report_categories() as $item): ?><option <?= $category === $item ? 'selected' : '' ?>><?= e($item) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Status</label><select class="form-select" name="status"><option value="">All statuses</option><?php foreach (report_statuses() as $item): ?><option <?= $status === $item ? 'selected' : '' ?>><?= e($item) ?></option><?php endforeach; ?></select></div><div class="col-md-3 d-grid"><button class="btn btn-primary rounded-pill">Apply filters</button></div></form></section>
<section class="surface-card mb-3"><div id="admin-map" class="map-box"></div></section>
<section class="surface-card"><h2 class="h6 fw-bold mb-3">Reported locations</h2><div class="admin-table-wrap"><table class="table table-hover align-middle"><thead><tr><th>Reference</th><th>Category</th><th>Area</th><th>Coordinates</th><th>Correct coordinates</th></tr></thead><tbody><?php foreach ($rows as $item): ?><tr><td><?= e($item['reference_number']) ?></td><td><?= e($item['category']) ?></td><td><?= e($item['location']) ?>, <?= e($item['barangay']) ?></td><td><?= e($item['latitude'] ?? '—') ?>, <?= e($item['longitude'] ?? '—') ?></td><td><form class="d-flex gap-1" method="post" action="../actions/admin.php"><?= csrf_field() ?><input type="hidden" name="action" value="update_location"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><input class="form-control form-control-sm" name="latitude" aria-label="Latitude" placeholder="Latitude" value="<?= e($item['latitude']) ?>"><input class="form-control form-control-sm" name="longitude" aria-label="Longitude" placeholder="Longitude" value="<?= e($item['longitude']) ?>"><button class="btn btn-primary btn-sm">Save</button></form></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="5" class="text-secondary">No report locations match the filters.</td></tr><?php endif; ?></tbody></table></div></section>
<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
document.addEventListener('DOMContentLoaded',()=>{const map=L.map('admin-map').setView([13.45,121.95],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const data=<?= json_encode(array_values(array_filter($rows,fn($r)=>$r['latitude']!==null&&$r['longitude']!==null)),JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;data.forEach(x=>L.marker([Number(x.latitude),Number(x.longitude)]).bindPopup('<b>'+String(x.reference_number).replace(/[&<>"]/g,'')+'</b><br>'+String(x.category).replace(/[&<>"]/g,'')+'<br>'+String(x.location).replace(/[&<>"]/g,'')+', '+String(x.barangay).replace(/[&<>"]/g,'')+'<br>'+String(x.status).replace(/[&<>"]/g,'')).addTo(map));setTimeout(()=>map.invalidateSize(),150)});
</script>
<?php admin_footer(); ?>
